head.script:
scwin.test = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo = {
        id: "dynamic_checkbox_" + rowIndex + "_" + colIndex,
        inputType: "checkbox",
        options: {}
    };
    return returnInfo;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.trigger1_onclick = function(e) {
    gridView1.setCellChecked(0, "col1", true);
};
scwin.trigger2_onclick = function(e) {
    alert("결과갑 다름" + gridView1.getCheckedIndex("col1").length);
};
scwin.trigger3_onclick = function(e) {
    alert("결과갑 다름" + gridView1.getCheckedIndex("col2").length);
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 "버튼1"을 클릭한다.
    //1. Execute the sample file and click "Button 1".
    //Verify step 1. "Button 1" is clicked (formerly "checkbox or radio" message)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').childNodes[0].getAttribute('checked') == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /** inputType custom 시 문제 있는 그리드 API 적용 안되는 항목
    gridView1.getCheckedIndex
    gridView1.getCheckedData
    gridView1.getCheckedJSON
    gridView1.getCheckedXML
    gridView1.checkAll
    gridView1.setCellChecked
    */
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
